"""报告静态资源：CSS 与 JS（从 generate_report.py 提取，消除 f-string 转义地狱）。
原内容逐字节保留：已从 f-string 的 {{ }} 双重括号还原为单括号，注入时由 generate_html 的 f-string 负责换行。"""

REPORT_CSS = ":root {\n  --bg: #fafaf9;\n  --card-bg: #ffffff;\n  --text: #1c1917;\n  --text-secondary: #57534e;\n  --border: #e7e5e4;\n  --accent-green: #059669;\n  --accent-amber: #d97706;\n  --accent-gray: #6b7280;\n  --shadow: 0 1px 3px rgba(28, 25, 23, 0.08), 0 1px 2px rgba(28, 25, 23, 0.04);\n  --shadow-md: 0 4px 6px rgba(28, 25, 23, 0.07), 0 2px 4px rgba(28, 25, 23, 0.04);\n  --radius: 12px;\n  --radius-sm: 8px;\n}\n\n* { margin: 0; padding: 0; box-sizing: border-box; }\n\nbody {\n  font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, \"Noto Sans SC\", sans-serif;\n  background: var(--bg);\n  color: var(--text);\n  line-height: 1.6;\n  padding: 2rem 1rem;\n}\n\n.container {\n  max-width: 900px;\n  margin: 0 auto;\n}\n\n/* Header */\n.report-header {\n  text-align: center;\n  margin-bottom: 3rem;\n  padding: 2.5rem 2rem;\n  background: var(--card-bg);\n  border-radius: var(--radius);\n  box-shadow: var(--shadow);\n}\n\n.report-header h1 {\n  font-size: 1.75rem;\n  font-weight: 700;\n  margin-bottom: 0.5rem;\n  color: var(--text);\n}\n\n.report-header .subtitle {\n  font-size: 1rem;\n  color: var(--text-secondary);\n  margin-bottom: 1.5rem;\n}\n\n.report-header .direction-tags {\n  display: flex;\n  justify-content: center;\n  gap: 0.5rem;\n  flex-wrap: wrap;\n}\n\n.direction-tag {\n  background: #f0fdf4;\n  color: var(--accent-green);\n  padding: 0.25rem 0.75rem;\n  border-radius: 99px;\n  font-size: 0.85rem;\n  font-weight: 500;\n  border: 1px solid #bbf7d0;\n}\n\n/* Stats bar */\n.stats-bar {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));\n  gap: 1rem;\n  margin-bottom: 2.5rem;\n}\n\n.stat-card {\n  background: var(--card-bg);\n  border-radius: var(--radius-sm);\n  padding: 1.25rem;\n  text-align: center;\n  box-shadow: var(--shadow);\n}\n\n.stat-card .stat-value {\n  font-size: 1.75rem;\n  font-weight: 700;\n  color: var(--text);\n}\n\n.stat-card .stat-label {\n  font-size: 0.8rem;\n  color: var(--text-secondary);\n  margin-top: 0.25rem;\n}\n\n.stat-card.green .stat-value { color: var(--accent-green); }\n.stat-card.amber .stat-value { color: var(--accent-amber); }\n.stat-card.gray .stat-value { color: var(--accent-gray); }\n.stat-card.blue .stat-value { color: #2563eb; }\n\n.badge-new {\n  display: inline-block;\n  background: #eff6ff;\n  color: #2563eb;\n  border: 1px solid #bfdbfe;\n  padding: 0.1rem 0.5rem;\n  border-radius: 99px;\n  font-size: 0.7rem;\n  font-weight: 600;\n  margin-top: 0.25rem;\n}\n\n/* Funnel */\n.funnel {\n  background: var(--card-bg);\n  border-radius: var(--radius);\n  padding: 1.5rem 2rem;\n  margin-bottom: 2.5rem;\n  box-shadow: var(--shadow);\n}\n\n.funnel h2 {\n  font-size: 1.1rem;\n  font-weight: 600;\n  margin-bottom: 1rem;\n}\n\n.funnel-steps {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  flex-wrap: wrap;\n}\n\n.funnel-step {\n  display: flex;\n  align-items: center;\n  gap: 0.4rem;\n  font-size: 0.85rem;\n  color: var(--text-secondary);\n}\n\n.funnel-step .num {\n  font-weight: 700;\n  font-size: 1.1rem;\n  color: var(--text);\n}\n\n.funnel-arrow {\n  color: var(--border);\n  font-size: 1.2rem;\n}\n\n/* Filter tabs */\n.filter-tabs {\n  display: flex;\n  gap: 0.5rem;\n  margin-bottom: 1.5rem;\n  flex-wrap: wrap;\n}\n\n.filter-tab {\n  padding: 0.5rem 1rem;\n  border-radius: 99px;\n  border: 1px solid var(--border);\n  background: var(--card-bg);\n  cursor: pointer;\n  font-size: 0.85rem;\n  font-weight: 500;\n  transition: all 0.2s;\n}\n\n.filter-tab:hover { border-color: var(--accent-green); color: var(--accent-green); }\n.filter-tab.active { background: var(--accent-green); color: white; border-color: var(--accent-green); }\n.filter-tab.active-b { background: var(--accent-amber); color: white; border-color: var(--accent-amber); }\n.filter-tab.active-c { background: var(--accent-gray); color: white; border-color: var(--accent-gray); }\n\n/* Job cards */\n.tier-section {\n  margin-bottom: 2rem;\n}\n\n.tier-section h2 {\n  font-size: 1.2rem;\n  font-weight: 600;\n  margin-bottom: 1rem;\n  padding-bottom: 0.5rem;\n  border-bottom: 2px solid var(--border);\n}\n\n.job-card {\n  background: var(--card-bg);\n  border-radius: var(--radius-sm);\n  padding: 1.25rem 1.5rem;\n  margin-bottom: 0.75rem;\n  box-shadow: var(--shadow);\n  transition: box-shadow 0.2s, transform 0.15s;\n  cursor: pointer;\n}\n\n.job-card:hover {\n  box-shadow: var(--shadow-md);\n  transform: translateY(-1px);\n}\n\n.card-header {\n  margin-bottom: 0.5rem;\n}\n\n.card-title-row {\n  display: flex;\n  justify-content: space-between;\n  align-items: flex-start;\n  gap: 1rem;\n}\n\n.job-title {\n  font-size: 1rem;\n  font-weight: 600;\n  color: var(--text);\n  flex: 1;\n}\n\n.score-badge {\n  min-width: 36px;\n  height: 36px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 8px;\n  font-size: 0.85rem;\n  font-weight: 700;\n  flex-shrink: 0;\n}\n\n.job-id-row {\n  display: flex;\n  align-items: center;\n  gap: 0.6rem;\n  margin-top: 0.2rem;\n}\n\n.job-id-label {\n  font-size: 0.7rem;\n  font-family: \"SF Mono\", \"Fira Code\", monospace;\n  color: var(--text-secondary);\n  background: var(--border);\n  padding: 0.1rem 0.4rem;\n  border-radius: 4px;\n}\n\n.job-link {\n  font-size: 0.75rem;\n  color: var(--accent-green);\n  text-decoration: none;\n  font-weight: 500;\n}\n\n.job-link:hover {\n  text-decoration: underline;\n}\n\n.job-title-link {\n  color: inherit;\n  text-decoration: none;\n}\n\n.job-title-link:hover {\n  color: var(--accent-green);\n  text-decoration: underline;\n}\n\n.job-meta {\n  font-size: 0.8rem;\n  color: var(--text-secondary);\n  margin-top: 0.25rem;\n}\n\n.tier-label {\n  font-size: 0.75rem;\n  font-weight: 600;\n  margin-top: 0.25rem;\n}\n\n.card-body {\n  display: none;\n  margin-top: 0.75rem;\n  padding-top: 0.75rem;\n  border-top: 1px solid var(--border);\n  font-size: 0.9rem;\n}\n\n.job-card.expanded .card-body { display: block; }\n\n.reasons ul {\n  margin: 0.25rem 0 0.5rem 1.2rem;\n  color: var(--text-secondary);\n}\n\n.reasons li { margin-bottom: 0.2rem; }\n\n.risks { margin: 0.5rem 0; }\n\n.risk-tag {\n  display: inline-block;\n  background: #fef2f2;\n  color: #dc2626;\n  padding: 0.15rem 0.5rem;\n  border-radius: 4px;\n  font-size: 0.8rem;\n  margin-right: 0.4rem;\n  margin-bottom: 0.3rem;\n}\n\n.advice {\n  margin-top: 0.5rem;\n  color: var(--text-secondary);\n  font-size: 0.85rem;\n  font-style: italic;\n}\n\n.scores-detail {\n  margin-top: 0.5rem;\n  display: flex;\n  gap: 1rem;\n  font-size: 0.75rem;\n  color: var(--text-secondary);\n}\n\n/* Condition tags (English / Core Team / Tech) */\n.card-tags {\n  display: flex;\n  gap: 0.35rem;\n  flex-wrap: wrap;\n  margin-top: 0.35rem;\n}\n\n.cond-tag {\n  display: inline-block;\n  padding: 0.1rem 0.5rem;\n  border-radius: 4px;\n  font-size: 0.7rem;\n  font-weight: 500;\n}\n\n.cond-tag.tag-eng {\n  background: #eff6ff;\n  color: #1d4ed8;\n  border: 1px solid #bfdbfe;\n}\n\n.cond-tag.tag-core {\n  background: #fef3c7;\n  color: #92400e;\n  border: 1px solid #fde68a;\n}\n\n.cond-tag.tag-tech {\n  background: #ecfdf5;\n  color: #065f46;\n  border: 1px solid #a7f3d0;\n}\n\n/* Footer */\n.report-footer {\n  text-align: center;\n  padding: 2rem;\n  color: var(--text-secondary);\n  font-size: 0.8rem;\n}\n\n/* Responsive */\n@media (max-width: 640px) {\n  body { padding: 1rem 0.5rem; }\n  .report-header { padding: 1.5rem 1rem; }\n  .report-header h1 { font-size: 1.3rem; }\n  .stats-bar { grid-template-columns: repeat(2, 1fr); }\n  .funnel-steps { flex-direction: column; align-items: flex-start; }\n  .funnel-arrow { display: none; }\n\n/* 投递时机徽标（Phase 8.3） */\n.badge-urgent { display: inline-block; margin-left: 0.4rem; padding: 0.1rem 0.5rem; border-radius: 999px; font-size: 0.72rem; font-weight: 600; background: #fef2f2; color: #dc2626; border: 1px solid #fecaca; }\n.badge-timing { display: inline-block; margin-left: 0.4rem; padding: 0.1rem 0.5rem; border-radius: 999px; font-size: 0.72rem; font-weight: 600; background: #fffbeb; color: #d97706; border: 1px solid #fde68a; }\n.badge-stale { display: inline-block; margin-left: 0.4rem; padding: 0.1rem 0.5rem; border-radius: 999px; font-size: 0.72rem; font-weight: 600; background: #f3f4f6; color: #6b7280; border: 1px solid #e5e7eb; }\n\n/* 趋势洞察（Phase 8.1） */\n.trend-section {\n  background: var(--card-bg);\n  border-radius: var(--radius);\n  padding: 1.5rem 2rem;\n  margin-bottom: 2.5rem;\n  box-shadow: var(--shadow);\n}\n.trend-section h2 { font-size: 1.1rem; font-weight: 600; margin-bottom: 1rem; }\n.trend-mode { font-size: 0.75rem; color: var(--text-secondary); font-weight: 400; }\n.trend-chart { margin: 1rem 0 1.5rem; }\n.trend-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 1.5rem;\n}\n.trend-sub h4 {\n  font-size: 0.9rem;\n  font-weight: 600;\n  margin-bottom: 0.6rem;\n  color: var(--text-secondary);\n}\n.trend-row {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  font-size: 0.82rem;\n  margin-bottom: 0.3rem;\n}\n.trend-label { width: 92px; flex-shrink: 0; color: var(--text-secondary); }\n.trend-bar { height: 10px; background: var(--accent-green); border-radius: 4px; display: inline-block; min-width: 2px; }\n.trend-num { font-weight: 700; width: 30px; flex-shrink: 0; }\n.trend-delta.green { color: var(--accent-green); font-weight: 600; }\n.trend-delta.amber { color: var(--accent-amber); font-weight: 600; }\n.trend-delta.gray { color: var(--accent-gray); }\n.trend-table { width: 100%; border-collapse: collapse; font-size: 0.8rem; }\n.trend-table th, .trend-table td { padding: 0.35rem 0.5rem; text-align: left; border-bottom: 1px solid var(--border); }\n.trend-table th { color: var(--text-secondary); font-weight: 600; }\n.trend-table td.green { color: var(--accent-green); font-weight: 600; }\n.trend-table td.amber { color: var(--accent-amber); font-weight: 600; }\n.trend-empty { color: var(--text-secondary); font-size: 0.85rem; font-style: italic; }\n.trend-fs { margin: 0.25rem 0 0 1.2rem; color: var(--text-secondary); font-size: 0.82rem; }\n@media (max-width: 640px) {\n  .trend-grid { grid-template-columns: 1fr; }\n}\n\n/* 竞争力动态（Phase 8.2） */\n.competitiveness-section {\n  background: var(--card-bg);\n  border-radius: var(--radius);\n  padding: 1.5rem 2rem;\n  margin-bottom: 2.5rem;\n  box-shadow: var(--shadow);\n}\n.competitiveness-section h2 { font-size: 1.2rem; font-weight: 600; margin: 0 0 1rem; }\n.comp-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; align-items: center; }\n.comp-report pre { white-space: pre-wrap; font-family: -apple-system, \"Segoe UI\", \"PingFang SC\", sans-serif; font-size: 0.9rem; line-height: 1.6; margin: 0; }\n.comp-radar { display: flex; justify-content: center; }\n.comp-radar svg { max-width: 100%; height: auto; }\n.comp-narrative { margin: 0 0 1rem; padding: 0.75rem 1rem; background: #f0f9ff; border: 1px solid #bae6fd; border-radius: var(--radius-sm); font-size: 0.9rem; color: var(--text); }\n.comp-narrative strong { color: #0369a1; margin-right: 0.35rem; }\n.comp-narrative p { margin: 0; display: inline; }\n@media (max-width: 640px) {\n  .comp-grid { grid-template-columns: 1fr; }\n}\n}"

REPORT_JS = "// Card expand/collapse\ndocument.querySelectorAll('.job-card').forEach(card => {\n  card.addEventListener('click', () => {\n    card.classList.toggle('expanded');\n  });\n});\n\n// Filter tabs\ndocument.querySelectorAll('.filter-tab').forEach(tab => {\n  tab.addEventListener('click', () => {\n    const filter = tab.dataset.filter;\n\n    // Update tab states\n    document.querySelectorAll('.filter-tab').forEach(t => {\n      t.classList.remove('active', 'active-b', 'active-c');\n    });\n    if (filter === 'A' || filter === 'all') tab.classList.add('active');\n    else if (filter === 'B') tab.classList.add('active-b');\n    else if (filter === 'C') tab.classList.add('active-c');\n\n    // Show/hide sections\n    document.querySelectorAll('.tier-section').forEach(section => {\n      const tier = section.dataset.tierSection;\n      if (filter === 'all' || filter === tier) {\n        section.style.display = '';\n      } else {\n        section.style.display = 'none';\n      }\n    });\n  });\n});\n\n// Auto-expand A-tier cards on load\ndocument.querySelectorAll('.job-card[data-tier=\"A\"]').forEach(card => {\n  card.classList.add('expanded');\n});"
